mapper.select:
SELECT fi.id,
fi.create_time,
fi.content_id
FROM flow_index fi


        AND fi.user_id = #{userId}


        AND fi.type = #{type}


        AND fi.content_module = #{contentModule}


        AND fi.content_id = #{contentId}



    LIMIT #{current},#{size}

SELECT COUNT(*)
FROM flow_index fi


        AND fi.user_id = #{userId}


        AND fi.type = #{type}


        AND fi.content_module = #{contentModule}


        AND fi.content_id = #{contentId}
